public class NDXPOPspecificDataManagementHistory extends common
{
}

Method.Source:
/// <summary>
/// PaffH 12.04.25
/// </summary>
/// <param name = "_nDXPOPspecificDataManagementLine">RefRecId</param>
/// <param name = "_refTableId">RefTableId</param>
/// <param name = "_refRecId">RefRecId</param>
/// <param name = "_refFieldId">RefFieldId</param>
/// <param name = "_oldValue">NDXFieldValueContainerOld</param>
/// <param name = "_newValue">NDXFieldValueContainerNew</param>
public static void logChanges(
    RefRecId _nDXPOPspecificDataManagementLine,
    RefTableId _refTableId,
    RefRecId _refRecId,
    RefFieldId _refFieldId,
    NDXFieldValueContainerOld _oldValue, 
    NDXFieldValueContainerNew _newValue,
    NDXChangeEventBasePOP _nDXChangeEventBasePOP = NDXChangeEventBasePOP::POPspecificDataManagement
    )
{
    NDXPOPspecificDataManagementHistory _nDXPOPspecificDataManagementHistory;
    _nDXPOPspecificDataManagementHistory.initValue();
    _nDXPOPspecificDataManagementHistory.NDXPOPspecificDataManagementLine = _nDXPOPspecificDataManagementLine;
    _nDXPOPspecificDataManagementHistory.RefTableId = _refTableId;
    _nDXPOPspecificDataManagementHistory.RefRecId = _refRecId;
    _nDXPOPspecificDataManagementHistory.RefFieldId = _refFieldId;
    _nDXPOPspecificDataManagementHistory.FieldValueContainerOld = _oldValue;
    _nDXPOPspecificDataManagementHistory.FieldValueContainerNew = _newValue;
    _nDXPOPspecificDataManagementHistory.ChangeEventBase = _nDXChangeEventBasePOP;
    _nDXPOPspecificDataManagementHistory.insert();
}

/// <summary>
/// PaffH 14.04.25
/// </summary>
/// <returns>TableName</returns>
[SysClientCacheDataMethod(true)]
display TableName tableName()
{
    return this.prefixFromTableId(this.RefTableId) +  tableId2Name(this.RefTableId);

}

/// <summary>
/// PaffH 14.04.25
/// </summary>
/// <returns>TableName</returns>
[SysClientCacheDataMethod(true)]
display TableName tableNameP()
{
    return this.prefixFromTableId(this.RefTableId) + tableId2PName(this.RefTableId);
}

/// <summary>
/// PaffH 15.04.25
/// </summary>
/// <param name = "_tableId">TableId</param>
/// <returns>prefix default / dim</returns>
protected str prefixFromTableId(TableId _tableId)
{
    const str prefixDefault = '01-';
    const str prefixDim = '02-';
    str prefix = '';
    switch (_tableId)
    {
        case tableNum(InventItemPurchSetup):
            InventItemPurchSetup inventItemPurchSetup;
            select firstonly InventDimId from inventItemPurchSetup where inventItemPurchSetup.RecId == this.RefRecId;
            prefix = inventItemPurchSetup.InventDimId == InventDim::inventDimIdBlank() ? prefixDefault : prefixDim;
            break;
        case tableNum(InventItemInventSetup):
            InventItemInventSetup inventItemInventSetup;
            select firstonly InventDimId from inventItemInventSetup where inventItemInventSetup.RecId == this.RefRecId;
            prefix = inventItemInventSetup.InventDimId == InventDim::inventDimIdBlank() ? prefixDefault : prefixDim;
            break;
        case tableNum(InventItemSalesSetup):
            InventItemSalesSetup inventItemSalesSetup;
            select firstonly InventDimId from inventItemSalesSetup where inventItemSalesSetup.RecId == this.RefRecId;
            prefix = inventItemSalesSetup.InventDimId == InventDim::inventDimIdBlank() ? prefixDefault : prefixDim;
            break;
    }
    return prefix;
}

