/// <summary>
/// PaffH 14.04.25
/// </summary>
/// <param name = "_newValue">boolean</param>
/// <returns>str</returns>
protected str any2String(boolean _newValue)
{
    DictField dictField = SysDictField::findFieldById(this.RefTableId, this.RefFieldId);
    Types typeBase = dictField.baseType();
    container conValue = _newValue ? this.FieldValueContainerNew : this.FieldValueContainerOld;
    anytype valFromCon = conPeek(conValue, 1);
    switch (typeBase)
    {
        case Types::Date:
            return date2StrUsr(valFromCon);
        case Types::Time:
            return valFromCon;
        case Types::Int64:
        case Types::Integer:
            return strLTrim(int2Str(valFromCon));
        case Types::BLOB:
            return '<<< Blob >>>';
        case Types::Container:
            return con2Str(valFromCon);
        case Types::String:
        case Types::RString:
        case Types::VarString:
            return valFromCon;
        case Types::Real:
            return strLTrim(num2Str(valFromCon, 15, 3, DecimalSeparator::Comma, ThousandSeparator::Dot));
        case Types::Enum:
            return strLTrim(int2Str(valFromCon));
        case Types::Guid:
            return guid2Str(valFromCon);
    }
    return '???';
}

