/// <summary>
/// PaffH 15.04.25
/// </summary>
public void initValue()
{
    super();
    this.ChangeEventBase = NDXChangeEventBasePOP::POPspecificDataManagement;
}

/// <summary>
/// PaffH 15.04.25
/// </summary>
/// <param name = "_inventTableRecId">RecId InventTable</param>
/// <param name = "_tableBuffer">Common</param>
/// <param name = "_refFieldId">RefFieldId</param>
/// <param name = "_oldValue">container</param>
/// <param name = "_newValue">container</param>
public static void saveChangeFromInventTable(RecId _inventTableRecId, Common _tableBuffer, RefFieldId _refFieldId, container _oldValue, container _newValue)
{
    NDXPOPspecificDataManagementHeader nDXPOPspecificDataManagementHeader;
    NDXPOPspecificDataManagementLine nDXPOPspecificDataManagementLine;
    while select nDXPOPspecificDataManagementLine
        where nDXPOPspecificDataManagementLine.InventTable == _inventTableRecId
        join nDXPOPspecificDataManagementHeader
        where nDXPOPspecificDataManagementHeader.RecId == nDXPOPspecificDataManagementLine.NDXPOPspecificDataManagementHeader
    {
        NDXPOPspecificDataManagementHistory::logChanges(
            nDXPOPspecificDataManagementLine.RecId
            , _tableBuffer.TableId
            , _tableBuffer.RecId
            , _refFieldId
            , _oldValue
            , _newValue
            , NDXChangeEventBasePOP::ItemspecificChange
            );
    }

}
